import React, { useState } from 'react';

const VMList = ({ vms, onSelect, onCreate, onStart, onStop }) => {
  const [newVM, setNewVM] = useState({ id: '', kernelPath: '', initrdPath: '', diskPath: '', kernelCmdline: '', memoryMB: 256, vcpus: 1 });
  const [advancedOpen, setAdvancedOpen] = useState(false);

  const handleCreate = () => {
    onCreate(newVM);
    setNewVM({ id: '', kernelPath: '', initrdPath: '', diskPath: '', kernelCmdline: '', memoryMB: 256, vcpus: 1 });
    setAdvancedOpen(false);
  };

  return (
    <div className="bg-gray-900 p-6 rounded-lg border border-gray-700 text-white">
      <h2 className="text-2xl font-bold mb-4">VM Instances</h2>
      <ul className="mb-6 space-y-2">
        {vms.map(vm => (
          <li key={vm.id} className="flex justify-between items-center p-3 bg-gray-800 rounded border border-gray-700">
            <span className="text-gray-100">{vm.id} <span className="text-gray-500">({vm.state})</span></span>
            <div className="space-x-2">
              <button
                onClick={() => onStart(vm.id)}
                className="bg-green-600 hover:bg-green-700 text-white px-3 py-1 rounded text-sm disabled:opacity-50 disabled:cursor-not-allowed"
                disabled={vm.state === 'Running'}
              >
                Start
              </button>
              <button
                onClick={() => onStop(vm.id)}
                className="bg-red-600 hover:bg-red-700 text-white px-3 py-1 rounded text-sm disabled:opacity-50 disabled:cursor-not-allowed"
                disabled={vm.state !== 'Running'}
              >
                Stop
              </button>
              <button
                onClick={() => onSelect(vm.id)}
                className="bg-blue-600 hover:bg-blue-700 text-white px-3 py-1 rounded text-sm"
              >
                Select
              </button>
            </div>
          </li>
        ))}
      </ul>
      <div className="border-t border-gray-700 pt-4">
        <h3 className="text-lg font-bold mb-3">Create New VM</h3>
        <input
          type="text"
          placeholder="VM ID"
          value={newVM.id}
          onChange={e => setNewVM({...newVM, id: e.target.value})}
          className="w-full p-2 bg-gray-800 border border-gray-600 rounded mb-2 text-white placeholder-gray-500"
        />
        <input
          type="text"
          placeholder="Kernel Path"
          value={newVM.kernelPath}
          onChange={e => setNewVM({...newVM, kernelPath: e.target.value})}
          className="w-full p-2 bg-gray-800 border border-gray-600 rounded mb-2 text-white placeholder-gray-500"
        />
        <input
          type="text"
          placeholder="Initrd Path (optional)"
          value={newVM.initrdPath}
          onChange={e => setNewVM({...newVM, initrdPath: e.target.value})}
          className="w-full p-2 bg-gray-800 border border-gray-600 rounded mb-2 text-white placeholder-gray-500"
        />
        <button
          onClick={() => setAdvancedOpen(!advancedOpen)}
          className="w-full bg-gray-700 hover:bg-gray-600 text-white px-3 py-2 rounded mb-3 text-sm"
        >
          {advancedOpen ? 'Hide Advanced Options' : 'Show Advanced Options'}
        </button>
        {advancedOpen && (
          <div className="bg-gray-800 p-3 rounded mb-3 border border-gray-600">
            <input
              type="text"
              placeholder="Disk Image Path (optional)"
              value={newVM.diskPath}
              onChange={e => setNewVM({...newVM, diskPath: e.target.value})}
              className="w-full p-2 bg-gray-700 border border-gray-600 rounded mb-2 text-white placeholder-gray-500"
            />
            <input
              type="text"
              placeholder="Kernel Command Line (optional)"
              value={newVM.kernelCmdline}
              onChange={e => setNewVM({...newVM, kernelCmdline: e.target.value})}
              className="w-full p-2 bg-gray-700 border border-gray-600 rounded mb-2 text-white placeholder-gray-500"
            />
            <p className="text-sm text-gray-400">Use the disk image path to boot from a local OS image and configure advanced kernel boot options.</p>
          </div>
        )}
        <input
          type="number"
          placeholder="Memory (MB)"
          value={newVM.memoryMB}
          onChange={e => setNewVM({...newVM, memoryMB: parseInt(e.target.value)})}
          className="w-full p-2 bg-gray-800 border border-gray-600 rounded mb-2 text-white placeholder-gray-500"
        />
        <input
          type="number"
          placeholder="vCPUs"
          value={newVM.vcpus}
          onChange={e => setNewVM({...newVM, vcpus: parseInt(e.target.value)})}
          className="w-full p-2 bg-gray-800 border border-gray-600 rounded mb-2 text-white placeholder-gray-500"
        />
        <button
          onClick={handleCreate}
          className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded w-full font-semibold"
        >
          Create VM
        </button>
      </div>
    </div>
  );
};

export default VMList;
